def lire_final(raw):
    import json
    def paires(rows):
        result={}
        for k,v in rows:
            if k in result: raise ValueError('doublon')
            result[k]=v
        return result
    value=json.loads(raw,object_pairs_hook=paires)
    if not isinstance(value,dict) or set(value)!={'type','text'} or value['type']!='final' or not isinstance(value['text'],str) or not value['text'].strip():
        raise ValueError('final invalide')
    return value['text']

exercise.check:
assert lire_final('{"type":"final","text":"5"}')=='5'
for raw in ['[]','{"type":"final","text":""}','{"type":"final","text":"x","text":"y"}']:
    try:lire_final(raw)
    except ValueError:pass
    else:raise AssertionError('contrat invalide accepté')
